import type { BossArt } from '../layer';
import { stageSheet, type StageArt, type StagePicture } from './sheet';
import type { Box } from '../sheet';

/**
 * The art of a character shown in stage pictures, as the boss layer wants it: asked for her on
 * every frame she is on screen, fetching her pictures the first time, and answering null until
 * they are in — she is not drawn, and nothing waits on her.
 *
 * A character's own page (`render/boss/<id>/art.ts`, generated by the cut) hands over her
 * pictures and where each lies; whoever knows how she moves adds that. So registering one is:
 *
 *     this.boss.register(VESPER.id, stageSource(loadVESPER, VESPER_STAGES, { move, lights }, VESPER.figure));
 */

/** A layout as the cut writes it: where each picture lies, and where its light lies. */
export type StageLayout = Readonly<Record<number, readonly [Box, Box | null]>>;

/** What a character adds to the template: how she moves, what light she throws, how she takes a hit. */
export type StageMotion = Pick<StageArt, 'move' | 'lights' | 'bob' | 'flash' | 'changeFlash'>;

/**
 * Makes the source of a character shown in stage pictures. `load` fetches and decodes her pictures
 * (once, however many times it is called in parallel); `layout` says where each lies; `figure` is
 * how many world units a figure unit of hers is.
 */
/** The source of a character shown in stage pictures: asked for her art, and told to fetch it ahead of time. */
export interface StageSource {
  (): BossArt | null;
  /** Fetches her pictures now, so that they are in hand before she is on screen. */
  preload(): Promise<void>;
}

export function stageSource(
  load: () => Promise<readonly (StagePicture | null)[]>,
  layout: StageLayout,
  motion: StageMotion,
  figure: number,
): StageSource {
  let sheet: ReturnType<typeof stageSheet> = null;
  let tried = false;
  let pending: Promise<void> | null = null;
  const bring = (): Promise<void> => {
    if (!pending)
      pending = load().then((pictures) => {
        sheet = stageSheet('stages', pictures, { stages: layout, ...motion });
        tried = true;
      });
    return pending;
  };
  const source = (): BossArt | null => {
    // Asked for before she was told to fetch: fetch now, and say nothing this frame.
    if (!tried && !pending) void source.preload();
    return sheet ? { sheet, scale: figure } : null;
  };
  source.preload = (): Promise<void> =>
    bring().catch(() => {
      tried = true;
    });
  return source;
}
